export default class BufferList {
  constructor(public buffers: Buffer[] = []) {}

  // Appends a buffer to the list, or prepends it when `atFront` is true.
  // Returns `this` to support method chaining.
  public add(buffer: Buffer, atFront?: boolean): this {
    this.buffers[atFront ? 'unshift' : 'push'](buffer)
    return this
  }

  // Adds a 16-bit signed integer encoded as two big-endian bytes.
  public addInt16(value: number, atFront?: boolean): this {
    return this.add(Buffer.from([value >>> 8, value >>> 0]), atFront)
  }

  // Adds a 32-bit signed integer encoded as four big-endian bytes.
  public addInt32(value: number, atFront?: boolean): this {
    return this.add(
      Buffer.from([(value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, (value >>> 0) & 0xff]),
      atFront
    )
  }

  // Adds a null-terminated C-style string (payload followed by a zero byte).
  public addCString(value: string, atFront?: boolean): this {
    const stringByteLength = Buffer.byteLength(value)
    const buffer = Buffer.alloc(stringByteLength + 1)
    buffer.write(value)
    buffer[stringByteLength] = 0
    return this.add(buffer, atFront)
  }

  // Adds a plain string without a null terminator.
  public addString(value: string, atFront?: boolean): this {
    const stringByteLength = Buffer.byteLength(value)
    const buffer = Buffer.alloc(stringByteLength)
    buffer.write(value)
    return this.add(buffer, atFront)
  }

  // Adds a single UTF-8 character.
  public addChar(char: string, atFront?: boolean): this {
    return this.add(Buffer.from(char, 'utf8'), atFront)
  }

  // Adds a single unsigned byte.
  public addByte(byte: number): this {
    return this.add(Buffer.from([byte]))
  }

  // Returns the combined byte length of all stored buffers.
  public getTotalByteLength(): number {
    return this.buffers.reduce((totalLength, buffer) => totalLength + buffer.length, 0)
  }

  // Concatenates all buffers into a single Buffer.
  // If `prependLength` is true, a 32-bit length prefix is added first
  // (the prefix accounts for its own 4 bytes, hence `totalLength + 4`).
  // If `delimiterChar` is provided, it is prepended before the payload.
  public join(prependLength?: boolean, delimiterChar?: string): Buffer {
    let totalLength = this.getTotalByteLength()

    if (prependLength) {
      this.addInt32(totalLength + 4, true)
      return this.join(false, delimiterChar)
    }

    if (delimiterChar) {
      this.addChar(delimiterChar, true)
      totalLength++
    }

    const result = Buffer.alloc(totalLength)
    let writeIndex = 0

    this.buffers.forEach((buffer) => {
      buffer.copy(result, writeIndex, 0)
      writeIndex += buffer.length
    })

    return result
  }
}